import{_ as e,o as a,c as s,ag as o}from"./chunks/framework.DQQHyi2x.js";const g=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md"}'),r={name:"guide/index.md"};function n(i,t,d,l,c,u){return a(),s("div",null,[...t[0]||(t[0]=[o('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>Claude Deck is a self-hosted web application for visualizing and managing <a href="https://docs.anthropic.com/en/docs/claude-code" target="_blank" rel="noreferrer">Claude Code</a> configuration. It provides a unified interface for managing MCP servers, plugins, slash commands, hooks, agents, permissions, usage tracking, and other Claude Code extensions.</p><h2 id="why-claude-deck" tabindex="-1">Why Claude Deck? <a class="header-anchor" href="#why-claude-deck" aria-label="Permalink to &quot;Why Claude Deck?&quot;">​</a></h2><p>Claude Code stores configuration across multiple JSON files and directories (<code>~/.claude.json</code>, <code>~/.claude/settings.json</code>, <code>.claude/settings.json</code>, <code>.mcp.json</code>, and more). Managing these files manually is tedious and error-prone. Claude Deck gives you a visual dashboard to:</p><ul><li><strong>See everything at a glance</strong> — dashboard with counts, session activity, and context window usage</li><li><strong>Edit configuration visually</strong> — no more hand-editing JSON files</li><li><strong>Manage MCP servers</strong> — add, test, and configure servers with OAuth support</li><li><strong>Track usage</strong> — monitor token costs, billing blocks, and daily/monthly trends</li><li><strong>Browse sessions</strong> — view conversation transcripts with tool use details</li><li><strong>Monitor live sessions</strong> — attach to running Claude Code terminals via CC Bridge</li></ul><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><p>Claude Deck covers all aspects of Claude Code configuration:</p><table tabindex="0"><thead><tr><th>Category</th><th>Features</th></tr></thead><tbody><tr><td><strong>Core Config</strong></td><td>Settings editor, MCP servers, slash commands</td></tr><tr><td><strong>Extensions</strong></td><td>Plugins, hooks, permissions, agents, skills</td></tr><tr><td><strong>Monitoring</strong></td><td>Sessions, usage tracking, context window, CC Bridge</td></tr><tr><td><strong>Customization</strong></td><td>Output styles, status line, memory</td></tr><tr><td><strong>Management</strong></td><td>Projects, plans, backup &amp; restore</td></tr></tbody></table><h2 id="tech-stack" tabindex="-1">Tech Stack <a class="header-anchor" href="#tech-stack" aria-label="Permalink to &quot;Tech Stack&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Technology</th></tr></thead><tbody><tr><td>Backend</td><td>Python 3.11+ with FastAPI</td></tr><tr><td>Frontend</td><td>React 19 + TypeScript + Vite 7</td></tr><tr><td>UI</td><td>shadcn/ui + Tailwind CSS</td></tr><tr><td>Charts</td><td>Recharts</td></tr><tr><td>Database</td><td>SQLite (async via SQLAlchemy + aiosqlite)</td></tr></tbody></table><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="/docs/guide/installation.html">Installation</a> — get Claude Deck running locally</li><li><a href="/docs/guide/quick-start.html">Quick Start</a> — explore the dashboard in 5 minutes</li><li><a href="/docs/guide/architecture.html">Architecture</a> — understand how the app is built</li></ul>',12)])])}const p=e(r,[["render",n]]);export{g as __pageData,p as default};
